"""Böcklin capitals, letter by letter, from the same standard parts + the swash that passes over the stem."""
from core import K, lens, loop, over, W
def stem(x, y0=0, y1=700, a=True, b=True, w=1.0): return K((x, y0, 90, w), (x, (y0 + y1) / 2, 90, .96 * w), (x, y1, 90, w), cut=(a, b))
def foot(x, l=118, r=118): return lens(x, 0, l, r)
def topl(x, l=118, r=118): return lens(x, 700, l, r, up=True)
def topbar(x0, x1, y=672, w=.42): return K((x0, y - 16, 12, .28), ((x0 + x1) / 2, y + 2, 0, w), (x1, y - 8, -6, .5))
def curl(x, y):              # the blob a swash starts from (top left of B D E F H K M N P R)
    return [(x + 35, y - 45, 150, .45), (x, y, 90, .8), (x + 40, y + 30, 0, .55)]
def swash(x0, y0, pts, halo=.14):  # a hairline out of the left curl, passing over the stem with a white outline
    return over(K((x0, y0, 160, .8), (x0 + 45, y0 - 20, -25, .55), *pts), halo)
